select c.relname as table_name, pol.polname, pol.polcmd, pol.polpermissive, position('is_studio_owner(' in lower(coalesce(pg_catalog.pg_get_expr(pol.polqual, pol.polrelid), ''))) > 0 as uses_owner, position('is_studio_member(' in lower(coalesce(pg_catalog.pg_get_expr(pol.polqual, pol.polrelid), ''))) > 0 as uses_member, array(select r.rolname from pg_catalog.pg_roles r where r.oid = any (pol.polroles) order by r.rolname) as roles from pg_catalog.pg_policy pol join pg_catalog.pg_class c on c.oid = pol.polrelid where c.relnamespace = 'public'::pg_catalog.regnamespace and c.relname in ('payment_charge_attempts', 'manual_fee_charge_attempts', 'appointment_settlements') and pol.polcmd in ('r', '*') order by c.relname, pol.polname